import XCTest
@testable import KeyForge

// Les vecteurs de brocolis-proto (proto/vectors.json, sessions_v4 et primitives) :
// ML-KEM-768 et le protocole v4 de KeyForge doivent les retrouver octet pour octet.
// Générés à partir du dépôt https://github.com/maxlestage/brocolis.
final class BrocolisV4Tests: XCTestCase {
    private let crypto = AppleCrypto.self

    private func hex(_ s: String) -> [UInt8] {
        var out = [UInt8]()
        var i = s.startIndex
        while i < s.endIndex {
            let j = s.index(i, offsetBy: 2)
            out.append(UInt8(s[i..<j], radix: 16)!)
            i = j
        }
        return out
    }

    private func toHex(_ b: [UInt8]) -> String { b.map { String(format: "%02x", $0) }.joined() }

    // MARK: ML-KEM-768

    func testMLKEMVectors() throws {
        let seed = hex("196692ff29cef60343b64ca565974de4d1ddc2c3544dc8229942bedfc5b307b1d6560f007f09bc80e3c065880830da434d0c9ce884789e1032922b3a590e08b8")
        let ek = MLKEM768.publicKey(seed: seed)
        XCTAssertEqual(toHex(ek), "")
        let encapsulated = try XCTUnwrap(MLKEM768.encapsulate(ek: ek, m: hex("65dae7262a48cccb45d7f26963574ef112f588e14fa635ad3c079705a3abee5e")))
        XCTAssertEqual(toHex(encapsulated.ciphertext), "")
        XCTAssertEqual(toHex(encapsulated.shared), "a3469bb3b836ed87547d15af12f43ba328928ddc6af3df1a07d0c07198b1e42f")
        XCTAssertEqual(MLKEM768.decapsulate(seed: seed, ciphertext: encapsulated.ciphertext), encapsulated.shared)
        var tampered = encapsulated.ciphertext
        tampered[7] ^= 0x01
        XCTAssertNotEqual(MLKEM768.decapsulate(seed: seed, ciphertext: tampered), encapsulated.shared)
        var invalid = ek
        invalid[0] = 0xFF
        invalid[1] |= 0x0F  // premier coefficient = 4 095 ≥ q
        XCTAssertFalse(MLKEM768.isValidEncapsulationKey(invalid))
    }

    func testHashes() {
        XCTAssertEqual(toHex(PureSHA256.hash(Array("abc".utf8))), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")
        XCTAssertEqual(toHex(PureSHA3.sha256([])), "a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a")
        XCTAssertEqual(
            toHex(PureSHA256.hkdf(salt: Array(0...12), ikm: [UInt8](repeating: 0x0b, count: 22), info: Array(0xf0...0xf9), length: 42)),
            "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865"
        )
    }

    // MARK: Paquet de clés

    private func bob() -> BrocolisDevice {
        BrocolisDevice(
            identityDH: hex("df9d1a1171cacadba635eadc4e020395fa6f994c19a8af2af2ed5bf3130e1232"), identitySign: hex("1f9492d3fc6921272361c7aea0b69f41e6abde4dfc332213f8325601c862ddbe"),
            spkID: 2, spkSecret: hex("0ce18c0acde292c10f3e48c4013d180fc94508427feb4d90c77d91ec1b497f74"),
            pqID: 102, pqSeed: hex("c92f24ced7340397abf908c58ee7ce8b3931b97b40c790437b2483cf08aeb70b05eb651585e47a9b13d86a3bdb363d290c96a05b87ec511404317eca18e9eb65"), createdAt: Date()
        )
    }

    func testBundleVector() throws {
        let bundle = try BrocolisKeyBundle.parse(bytes: hex(""), crypto: crypto)
        XCTAssertEqual(bundle.fingerprint, "87A4-7F01-07DA-B4C6")
        XCTAssertEqual(toHex(bundle.bytes), "")
        // Rebâti depuis les secrets : mêmes clés ; les signatures (CryptoKit peut les
        // tirer au hasard) doivent seulement être valides.
        let rebuilt = try bob().bundle(crypto: crypto)
        XCTAssertEqual(rebuilt.identityDH, bundle.identityDH)
        XCTAssertEqual(rebuilt.identitySign, bundle.identitySign)
        XCTAssertEqual(rebuilt.spk, bundle.spk)
        XCTAssertEqual(rebuilt.pqKey, bundle.pqKey)
        XCTAssertNoThrow(try rebuilt.verify(crypto: crypto))
        // Un paquet altéré est refusé.
        var altered = hex("")
        altered[200] ^= 0x01
        XCTAssertThrowsError(try BrocolisKeyBundle.parse(bytes: altered, crypto: crypto))
    }

    // MARK: Messages v4

    func testFirstMessageVector() throws {
        let bundle = try BrocolisKeyBundle.parse(bytes: hex(""), crypto: crypto)
        let token = try BrocolisV4.encrypt(
            "Salut Bob 🥦", to: bundle, identitySecret: hex("b3a9df2b81e880b5f566c3169f12a0d0a58f29dccf725faf16f7218f8dcbbd55"), crypto: crypto,
            ekSecret: hex("350c6b680f4d60aab0fd6fa43379055c4d06937847f30a6324d6b452972a57e5"), ratchetSecret: hex("a53d621e718be93fc4bf031cf6aecca2214729efacc369616a72bec80e2a9f3c"), kemM: hex("46cb9afc66d452010ab232121a274a98ff48508b003acdaad33ce73264dc54c9"), kemSeed: hex("a075910f848b967e37a3fa39818f83752a9e56e66f1b132795cff89e8957f2b3a4a5b75f1f9a1465cd07b45b9339ba0190ed903145360d118c2e63ade219d89f")
        )
        XCTAssertEqual(token, "[[BROCOLIS:v4:]]")

        var device = bob()
        let received = try BrocolisV4.accept("[[BROCOLIS:v4:]]", device: &device, crypto: crypto)
        XCTAssertEqual(received.text, "Salut Bob 🥦")
        XCTAssertEqual(toHex(received.senderIdentity), "ac8ec3ec21dd849db93ac979074d7344196ace8dd0f199fc6c965b007ac5c515")
        XCTAssertThrowsError(try BrocolisV4.accept("[[BROCOLIS:v4:]]", device: &device, crypto: crypto)) {
            XCTAssertEqual($0 as? BrocolisV4Error, .replay)
        }
        var other = bob()
        XCTAssertEqual(try BrocolisV4.accept("[[BROCOLIS:v4:]]", device: &other, crypto: crypto).text, "Tu me lis ?")
        var stranger = BrocolisDevice.generate()
        XCTAssertThrowsError(try BrocolisV4.accept("[[BROCOLIS:v4:]]", device: &stranger, crypto: crypto)) {
            XCTAssertEqual($0 as? BrocolisV4Error, .notForMe)
        }
    }

    func testSharedKeyVector() throws {
        let key = hex("22424a62fa26913b673e554d4440f674a2c8af2fc3a27adfb2a16aade0f6b88e")
        let token = try BrocolisV4.encryptPSK("Salut Bob 🥦", key: key, crypto: crypto, ekSecret: hex("1791f31d76ca1d758824f7a4c3da219a89de42f1eb341b324b89e9484800de8c"), kemSeed: hex("cb96fa84385cc08c1ebe5d6d1acfc9f74cab30ea5717c91f0100653f0f7b9906e40a88cdd8a1d73febbc114f560c74e3ebe2263c2b9dd52e5786323afd6cf4f4"))
        XCTAssertEqual(token, "[[BROCOLIS:v4:]]")
        XCTAssertEqual(try BrocolisV4.acceptPSK("[[BROCOLIS:v4:]]", key: key, crypto: crypto), "Salut Bob 🥦")
        XCTAssertEqual(try BrocolisV4.acceptPSK("[[BROCOLIS:v4:]]", key: key, crypto: crypto), "Tu me lis ?")
        XCTAssertThrowsError(try BrocolisV4.acceptPSK("[[BROCOLIS:v4:]]", key: [UInt8](repeating: 1, count: 32), crypto: crypto))
    }

    func testRoundTrip() throws {
        var me = BrocolisDevice.generate()
        let you = BrocolisDevice.generate()
        let bundle = try BrocolisKeyBundle.parse(me.bundle(crypto: crypto).base64, crypto: crypto)
        let token = try BrocolisV4.encrypt("Galet-Phare7-Sorbet 🥦", to: bundle, from: you, crypto: crypto)
        XCTAssertTrue(token.hasPrefix("[[BROCOLIS:v4:"))
        let received = try BrocolisV4.accept("Pour toi : " + token + " !", device: &me, crypto: crypto)
        XCTAssertEqual(received.text, "Galet-Phare7-Sorbet 🥦")
        XCTAssertEqual(received.senderIdentity, try crypto.x25519Public(secret: you.identityDH))
    }

    func testVaultBackupIsV4AndOldBackupsStillOpen() throws {
        let items = [VaultItem(title: "GitHub", username: "max", password: "Tg7#qP!m2Lz@Wv9$")]
        let text = try VaultBackup.export(items, phrase: "Galet-Phare7-Sorbet", params: .minimum, crypto: crypto)
        XCTAssertTrue(text.contains("[[BROCOLIS:v4:"))
        XCTAssertEqual(try VaultBackup.open(text, phrase: "Galet-Phare7-Sorbet", crypto: crypto).first?.password, "Tg7#qP!m2Lz@Wv9$")
        XCTAssertThrowsError(try VaultBackup.open(text, phrase: "mauvaise phrase", crypto: crypto))

        let key = Brocolis.randomBytes(32)
        let protected = try Brocolis.protectKeyV2(
            key, phrase: "Galet-Phare7-Sorbet", params: .minimum,
            salt: Brocolis.randomBytes(16), nonce: Brocolis.randomBytes(12), crypto: crypto
        )
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        let json = String(decoding: try encoder.encode(VaultBackupPayload(exportedAt: Date(), items: items)), as: UTF8.self)
        let old = protected + "\n" + (try Brocolis.sealTokenV1(json, key: key, nonce: Brocolis.randomBytes(12), crypto: crypto))
        XCTAssertEqual(try VaultBackup.open(old, phrase: "Galet-Phare7-Sorbet", crypto: crypto).count, 1)
    }
}
